package vn.hust.restaurant.repository;
import java.sql.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.Employee;
public class EmployeeRepository{
 public List<Employee> findAll(String k)throws SQLException{List<Employee>o=new ArrayList<>();k=k==null?"":k;String s="""
 SELECT nv.MaNhanVien,nv.MaNhanVienCode,nv.HoTen,nv.CCCD,nv.SDT,nv.Email,nv.DiaChi,nv.VaiTro,nv.TrangThaiLamViec,tk.TenDangNhap,tk.TrangThai
 FROM NhanVien nv LEFT JOIN TaiKhoan tk ON tk.MaNhanVien=nv.MaNhanVien WHERE (?='' OR nv.HoTen LIKE '%'+?+'%' OR nv.SDT LIKE '%'+?+'%') ORDER BY nv.HoTen
 """;try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,k);p.setString(2,k);p.setString(3,k);try(ResultSet r=p.executeQuery()){while(r.next())o.add(new Employee(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11)));}}return o;}
 public int save(Employee x)throws SQLException{if(x.id()==0){String s="INSERT NhanVien(MaNhanVienCode,HoTen,CCCD,SDT,Email,DiaChi,VaiTro,TrangThaiLamViec) OUTPUT INSERTED.MaNhanVien VALUES(?,?,?,?,?,?,?,'DANG_LAM')";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,x.code());p.setString(2,x.fullName());p.setString(3,x.citizenId());p.setString(4,x.phone());p.setString(5,x.email());p.setString(6,x.address());p.setString(7,x.role());try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}String s="UPDATE NhanVien SET MaNhanVienCode=?,HoTen=?,CCCD=?,SDT=?,Email=?,DiaChi=?,VaiTro=?,TrangThaiLamViec=? WHERE MaNhanVien=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,x.code());p.setString(2,x.fullName());p.setString(3,x.citizenId());p.setString(4,x.phone());p.setString(5,x.email());p.setString(6,x.address());p.setString(7,x.role());p.setString(8,x.workStatus());p.setInt(9,x.id());p.executeUpdate();return x.id();}}
 public void createOrResetAccount(int employeeId,String username,String passwordHash)throws SQLException{Database.inTransaction(c->{try(PreparedStatement q=c.prepareStatement("SELECT MaTaiKhoan FROM TaiKhoan WHERE MaNhanVien=?")){q.setInt(1,employeeId);try(ResultSet r=q.executeQuery()){if(r.next()){try(PreparedStatement p=c.prepareStatement("UPDATE TaiKhoan SET TenDangNhap=?,MatKhauHash=?,TrangThai='HOAT_DONG',SoLanDangNhapSai=0,KhoaDen=NULL WHERE MaNhanVien=?")){p.setString(1,username);p.setString(2,passwordHash);p.setInt(3,employeeId);p.executeUpdate();}}else{try(PreparedStatement p=c.prepareStatement("INSERT TaiKhoan(TenDangNhap,MatKhauHash,TrangThai,MaNhanVien) VALUES(?,?,'HOAT_DONG',?)")){p.setString(1,username);p.setString(2,passwordHash);p.setInt(3,employeeId);p.executeUpdate();}}}}return null;});}
 public void lockAccount(int employeeId,boolean locked)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE TaiKhoan SET TrangThai=? WHERE MaNhanVien=?")){p.setString(1,locked?"BI_KHOA":"HOAT_DONG");p.setInt(2,employeeId);p.executeUpdate();}}
}
